import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { calendarCellStyles } from './date-picker.styles.js';

/**
 * Individual day cell in a calendar grid.
 *
 * @element bl-calendar-cell
 */
@customElement('bl-calendar-cell')
export class BlCalendarCell extends LitElement {
  static override styles = [tokens, calendarCellStyles];

  /** ISO date string for this cell. */
  @property()
  date = '';

  /** Day number to display. */
  @property({ type: Number })
  day = 0;

  /** Whether this day is outside the current month. */
  @property({ type: Boolean, reflect: true, attribute: 'outside-month' })
  outsideMonth = false;

  /** Whether this is today. */
  @property({ type: Boolean, reflect: true })
  today = false;

  /** Whether this day is selected. */
  @property({ type: Boolean, reflect: true })
  selected = false;

  /** Whether this day is disabled. */
  @property({ type: Boolean, reflect: true })
  disabled = false;

  private _handleClick = (): void => {
    if (this.disabled) return;
    this.dispatchEvent(
      new CustomEvent('bl-cell-click', {
        detail: { date: this.date },
        composed: true,
        bubbles: true,
      }),
    );
  };

  protected override render() {
    return html`
      <button
        part="button"
        ?disabled=${this.disabled}
        aria-label=${this.date}
        aria-selected=${this.selected ? 'true' : 'false'}
        tabindex=${this.selected ? '0' : '-1'}
        @click=${this._handleClick}
      >
        ${this.day}
      </button>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-calendar-cell': BlCalendarCell;
  }
}

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { calendarStyles } from './date-picker.styles.js';
import { CalendarController } from '../controllers/calendar.js';

/**
 * Standalone month calendar with `role="grid"`.
 * Works as inline calendar or inside bl-date-picker.
 *
 * @element bl-calendar
 * @fires bl-date-change - Emitted when a date is selected.
 */
@customElement('bl-calendar')
export class BlCalendar extends LitElement {
  static override styles = [tokens, calendarStyles];

  private _cal = new CalendarController(this);

  /** Currently selected date (ISO YYYY-MM-DD). */
  @property()
  value = '';

  /** Minimum selectable date (ISO YYYY-MM-DD). */
  @property()
  min = '';

  /** Maximum selectable date (ISO YYYY-MM-DD). */
  @property()
  max = '';

  /** Locale for month/day names. */
  @property()
  locale = '';

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'grid');
    this.setAttribute('aria-label', 'Calendar');
    this.addEventListener('keydown', this._handleKeyDown);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('keydown', this._handleKeyDown);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('min')) this._cal.setMin(this.min);
    if (changed.has('max')) this._cal.setMax(this.max);
    if (changed.has('value') && this.value) this._cal.goToDate(this.value);
  }

  private _handleKeyDown = (e: KeyboardEvent): void => {
    // PageUp/PageDown for month navigation
    if (e.key === 'PageUp') {
      e.preventDefault();
      if (e.shiftKey) this._cal.prevYear();
      else this._cal.prevMonth();
    } else if (e.key === 'PageDown') {
      e.preventDefault();
      if (e.shiftKey) this._cal.nextYear();
      else this._cal.nextMonth();
    }
  };

  private _handleDateClick(date: string, disabled: boolean): void {
    if (disabled) return;
    this.value = date;
    this.dispatchEvent(
      new CustomEvent('bl-date-change', {
        detail: { value: date },
        composed: true,
        bubbles: true,
      }),
    );
  }

  protected override render() {
    const grid = this._cal.getDays();
    const weekdays = this._cal.weekdays;

    return html`
      <div class="calendar" part="calendar">
        <div class="header" part="header">
          <span class="month-year">${this._cal.monthName} ${this._cal.year}</span>
          <div class="nav-buttons">
            <button
              class="nav-btn"
              aria-label="Previous month"
              @click=${() => this._cal.prevMonth()}
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <polyline points="15 18 9 12 15 6"></polyline>
              </svg>
            </button>
            <button
              class="nav-btn"
              aria-label="Next month"
              @click=${() => this._cal.nextMonth()}
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <polyline points="9 18 15 12 9 6"></polyline>
              </svg>
            </button>
          </div>
        </div>

        <div class="weekdays" role="row">
          ${weekdays.map((d) => html`<span class="weekday" role="columnheader">${d}</span>`)}
        </div>

        <div class="days">
          ${grid.map((week) =>
            week.map(
              (day) => html`
                <bl-calendar-cell
                  .date=${day.date}
                  .day=${day.day}
                  ?outside-month=${!day.currentMonth}
                  ?today=${day.today}
                  ?selected=${this.value === day.date}
                  ?disabled=${day.disabled}
                  @bl-cell-click=${() => this._handleDateClick(day.date, day.disabled)}
                ></bl-calendar-cell>
              `,
            ),
          )}
        </div>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-calendar': BlCalendar;
  }
}

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { dateFieldStyles } from './date-picker.styles.js';
import type { SegmentType } from './date-segment.js';

/**
 * Segmented date input container.
 * Display format is locale-driven via `Intl.DateTimeFormat.formatToParts()`.
 *
 * @element bl-date-field
 * @fires bl-date-input - Emitted during segment editing.
 * @fires bl-date-field-trigger - Emitted when the calendar trigger is clicked.
 */
@customElement('bl-date-field')
export class BlDateField extends LitElement {
  static override styles = [tokens, dateFieldStyles];

  /** Current date value (ISO YYYY-MM-DD). */
  @property()
  value = '';

  /** Locale for segment order (MDY vs DMY vs YMD). */
  @property()
  locale = '';

  /** Whether to show the calendar trigger button. */
  @property({ type: Boolean, attribute: 'show-trigger' })
  showTrigger = false;

  private _month = 0;
  private _day = 0;
  private _year = 0;

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('value') && this.value) {
      const parts = this.value.split('-').map(Number);
      this._year = parts[0] ?? 0;
      this._month = parts[1] ?? 0;
      this._day = parts[2] ?? 0;
    }
  }

  /** Get segment order based on locale. */
  private _getSegmentOrder(): SegmentType[] {
    try {
      const fmt = new Intl.DateTimeFormat(this.locale || undefined, {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
      });
      const parts = fmt.formatToParts(new Date(2000, 0, 1));
      const order: SegmentType[] = [];
      for (const part of parts) {
        if (part.type === 'month') order.push('month');
        else if (part.type === 'day') order.push('day');
        else if (part.type === 'year') order.push('year');
      }
      return order.length === 3 ? order : ['month', 'day', 'year'];
    } catch {
      return ['month', 'day', 'year'];
    }
  }

  private _getSegmentValue(type: SegmentType): number {
    switch (type) {
      case 'month': return this._month;
      case 'day': return this._day;
      case 'year': return this._year;
    }
  }

  private _getPlaceholder(type: SegmentType): string {
    switch (type) {
      case 'month': return 'MM';
      case 'day': return 'DD';
      case 'year': return 'YYYY';
    }
  }

  private _handleSegmentChange = (e: CustomEvent<{ type: SegmentType; value: number }>): void => {
    e.stopPropagation();
    const { type, value } = e.detail;
    switch (type) {
      case 'month': this._month = value; break;
      case 'day': this._day = value; break;
      case 'year': this._year = value; break;
    }

    if (this._month > 0 && this._day > 0 && this._year > 0) {
      const m = String(this._month).padStart(2, '0');
      const d = String(this._day).padStart(2, '0');
      const y = String(this._year).padStart(4, '0');
      this.value = `${y}-${m}-${d}`;
      this.dispatchEvent(
        new CustomEvent('bl-date-input', {
          detail: { value: this.value },
          composed: true,
          bubbles: true,
        }),
      );
    }
  };

  private _handleSegmentNext = (e: Event): void => {
    e.stopPropagation();
    // Move focus to next segment
    const segments = Array.from(this.shadowRoot!.querySelectorAll('bl-date-segment'));
    const current = (e.target as HTMLElement).closest?.('bl-date-segment') ?? e.composedPath().find(
      (el) => el instanceof HTMLElement && el.tagName === 'BL-DATE-SEGMENT',
    ) as HTMLElement | undefined;
    if (!current) return;
    const idx = segments.indexOf(current as any);
    if (idx !== -1 && idx + 1 < segments.length) {
      const next = segments[idx + 1] as HTMLElement;
      requestAnimationFrame(() => next.shadowRoot?.querySelector<HTMLElement>('.segment')?.focus());
    }
  };

  private _handleTriggerClick = (): void => {
    this.dispatchEvent(
      new CustomEvent('bl-date-field-trigger', {
        composed: true,
        bubbles: true,
      }),
    );
  };

  protected override render() {
    const order = this._getSegmentOrder();

    return html`
      <div
        class="date-field"
        part="field"
        @bl-segment-change=${this._handleSegmentChange}
        @bl-segment-next=${this._handleSegmentNext}
      >
        ${order.map((type, i) => html`
          ${i > 0 ? html`<span class="separator">/</span>` : ''}
          <bl-date-segment
            .type=${type}
            .value=${this._getSegmentValue(type)}
            .placeholder=${this._getPlaceholder(type)}
          ></bl-date-segment>
        `)}
        ${this.showTrigger
          ? html`
              <button class="calendar-trigger" aria-label="Open calendar" @click=${this._handleTriggerClick}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                  <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
                  <line x1="16" y1="2" x2="16" y2="6"></line>
                  <line x1="8" y1="2" x2="8" y2="6"></line>
                  <line x1="3" y1="10" x2="21" y2="10"></line>
                </svg>
              </button>
            `
          : ''}
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-date-field': BlDateField;
  }
}

