import { LitElement, html, nothing } from 'lit';
import { customElement, property, state } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { datePickerStyles } from './date-picker.styles.js';
import { OverlayController } from '../controllers/overlay.js';
import { AnimationController } from '../controllers/animation.js';
import { ClickOutsideController } from '../controllers/click-outside.js';

/**
 * Date picker with segmented input + calendar popup.
 * Internal representation is ISO `YYYY-MM-DD` strings.
 *
 * @element bl-date-picker
 * @fires bl-date-change - Emitted when the final date value is set.
 * @fires bl-date-input - Emitted during segment editing.
 */
@customElement('bl-date-picker')
export class BlDatePicker extends LitElement {
  static override styles = [tokens, datePickerStyles];

  private _overlay = new OverlayController(this, { offset: 4 });
  private _animation = new AnimationController(this, { enterDuration: 150, exitDuration: 100 });
  private _clickOutside = new ClickOutsideController(this, {
    onClickOutside: () => { if (this._popupVisible) this._closePopup(); },
    active: false,
  });

  /** Current date value (ISO YYYY-MM-DD). */
  @property()
  value = '';

  /** Locale for display format. */
  @property()
  locale = '';

  /** Minimum selectable date (ISO). */
  @property()
  min = '';

  /** Maximum selectable date (ISO). */
  @property()
  max = '';

  /** Whether the picker is disabled. */
  @property({ type: Boolean, reflect: true })
  disabled = false;

  /** Whether the calendar popup is open. */
  @property({ type: Boolean, reflect: true })
  open = false;

  @state()
  private _popupVisible = false;

  override connectedCallback(): void {
    super.connectedCallback();
    this.addEventListener('bl-date-field-trigger', this._handleTrigger as EventListener);
    this.addEventListener('bl-date-input', this._handleDateInput as EventListener);
    this.addEventListener('keydown', this._handleKeyDown);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('bl-date-field-trigger', this._handleTrigger as EventListener);
    this.removeEventListener('bl-date-input', this._handleDateInput as EventListener);
    this.removeEventListener('keydown', this._handleKeyDown);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('open')) {
      if (this.open) this._openPopup();
      else if (this._popupVisible) this._closePopup();
    }
  }

  private _handleTrigger = (): void => {
    if (this.disabled) return;
    this.open = !this.open;
  };

  private _handleDateInput = (e: CustomEvent<{ value: string }>): void => {
    e.stopPropagation();
    this.value = e.detail.value;
    this.dispatchEvent(
      new CustomEvent('bl-date-input', {
        detail: { value: this.value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  private _handleCalendarChange = (e: CustomEvent<{ value: string }>): void => {
    e.stopPropagation();
    this.value = e.detail.value;
    this.open = false;
    this.dispatchEvent(
      new CustomEvent('bl-date-change', {
        detail: { value: this.value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  private _handleKeyDown = (e: KeyboardEvent): void => {
    if (e.key === 'Escape' && this.open) {
      e.preventDefault();
      this.open = false;
    }
  };

  private async _openPopup(): Promise<void> {
    if (this._popupVisible) return;
    this._popupVisible = true;
    await this.updateComplete;

    const field = this.shadowRoot!.querySelector<HTMLElement>('bl-date-field');
    const popup = this.shadowRoot!.querySelector<HTMLElement>('.popup');
    if (!field || !popup) return;

    this._overlay.show(field, popup);
    this._animation.enter(popup);
    this._clickOutside.active = true;
  }

  private async _closePopup(): Promise<void> {
    if (!this._popupVisible) return;

    const popup = this.shadowRoot!.querySelector<HTMLElement>('.popup');
    if (popup) await this._animation.exit(popup);

    this._overlay.hide();
    this._clickOutside.active = false;
    this._popupVisible = false;
  }

  protected override render() {
    return html`
      <bl-date-field
        .value=${this.value}
        .locale=${this.locale}
        show-trigger
      ></bl-date-field>

      ${this._popupVisible
        ? html`
            <div class="popup" part="popup">
              <bl-calendar
                .value=${this.value}
                .min=${this.min}
                .max=${this.max}
                .locale=${this.locale}
                @bl-date-change=${this._handleCalendarChange}
              ></bl-calendar>
            </div>
          `
        : nothing}
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-date-picker': BlDatePicker;
  }
}

import { LitElement, html } from 'lit';
import { customElement, property, state } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { dateSegmentStyles } from './date-picker.styles.js';

export type SegmentType = 'month' | 'day' | 'year';

/**
 * Individual date segment with `role="spinbutton"`.
 * ArrowUp/Down increments, digit typing fills the value.
 *
 * @element bl-date-segment
 * @fires bl-segment-change - Emitted when the segment value changes.
 */
@customElement('bl-date-segment')
export class BlDateSegment extends LitElement {
  static override styles = [tokens, dateSegmentStyles];

  /** Type of segment. */
  @property()
  type: SegmentType = 'day';

  /** Current numeric value. */
  @property({ type: Number })
  value = 0;

  /** Placeholder text when empty. */
  @property()
  placeholder = '';

  @state()
  private _buffer = '';
  private _bufferTimer: ReturnType<typeof setTimeout> | null = null;

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'spinbutton');
    this.addEventListener('keydown', this._handleKeyDown);
    this.addEventListener('focus', this._handleFocus);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('keydown', this._handleKeyDown);
    this.removeEventListener('focus', this._handleFocus);
    if (this._bufferTimer) clearTimeout(this._bufferTimer);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('value') || changed.has('type')) {
      const { min, max } = this._getRange();
      this.setAttribute('aria-valuemin', String(min));
      this.setAttribute('aria-valuemax', String(max));
      this.setAttribute('aria-valuenow', String(this.value));
      this.setAttribute('aria-valuetext', this.value > 0 ? this._formatDisplay() : this.placeholder);
    }
  }

  private _getRange(): { min: number; max: number } {
    switch (this.type) {
      case 'month': return { min: 1, max: 12 };
      case 'day': return { min: 1, max: 31 };
      case 'year': return { min: 1900, max: 2099 };
    }
  }

  private _formatDisplay(): string {
    if (this.value <= 0) return '';
    switch (this.type) {
      case 'month': return String(this.value).padStart(2, '0');
      case 'day': return String(this.value).padStart(2, '0');
      case 'year': return String(this.value).padStart(4, '0');
    }
  }

  private _handleFocus = (): void => {
    this._buffer = '';
  };

  private _handleKeyDown = (e: KeyboardEvent): void => {
    const { min, max } = this._getRange();

    if (e.key === 'ArrowUp') {
      e.preventDefault();
      let next = this.value + 1;
      if (next > max) next = min;
      this._emitChange(next);
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      let next = this.value - 1;
      if (next < min) next = max;
      this._emitChange(next);
    } else if (/^\d$/.test(e.key)) {
      e.preventDefault();
      this._appendDigit(e.key);
    } else if (e.key === 'ArrowRight' || e.key === 'Tab') {
      // Let focus move to next segment (handled by parent)
    } else if (e.key === 'ArrowLeft') {
      // Let focus move to prev segment (handled by parent)
    } else if (e.key === 'Backspace') {
      e.preventDefault();
      this._emitChange(0);
    }
  };

  private _appendDigit(digit: string): void {
    this._buffer += digit;

    if (this._bufferTimer) clearTimeout(this._bufferTimer);
    this._bufferTimer = setTimeout(() => {
      this._buffer = '';
    }, 800);

    const num = parseInt(this._buffer, 10);
    const { min, max } = this._getRange();
    const maxDigits = this.type === 'year' ? 4 : 2;

    if (this._buffer.length >= maxDigits || num > max) {
      // Commit
      const clamped = Math.max(min, Math.min(max, num));
      this._emitChange(clamped);
      this._buffer = '';
      if (this._bufferTimer) clearTimeout(this._bufferTimer);

      // Move to next segment
      this.dispatchEvent(new CustomEvent('bl-segment-next', { composed: true, bubbles: true }));
    } else {
      this._emitChange(num);
    }
  }

  private _emitChange(value: number): void {
    this.value = value;
    this.dispatchEvent(
      new CustomEvent('bl-segment-change', {
        detail: { type: this.type, value },
        composed: true,
        bubbles: true,
      }),
    );
  }

  protected override render() {
    const display = this._formatDisplay();
    const isEmpty = !display;

    return html`
      <span
        class="segment ${isEmpty ? 'placeholder' : ''}"
        part="segment"
        tabindex="0"
      >${isEmpty ? this.placeholder : display}</span>
    `;
  }
